
package com.store.productservice.controller;
import com.store.productservice.dto.ProductRequest;import com.store.productservice.dto.ProductResponse;import com.store.productservice.service.ProductService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/products")
public class ProductController { private final ProductService service; public ProductController(ProductService service){this.service=service;} @GetMapping public List<ProductResponse> getAll(){return service.getAll();} @GetMapping("/{id}") public ProductResponse getById(@PathVariable Long id){return service.getById(id);} @PostMapping public ResponseEntity<ProductResponse> create(@Valid @RequestBody ProductRequest req){return new ResponseEntity<>(service.create(req), HttpStatus.CREATED);} @PutMapping("/{id}") public ProductResponse update(@PathVariable Long id, @Valid @RequestBody ProductRequest req){return service.update(id, req);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id); return ResponseEntity.noContent().build();} @GetMapping("/search") public List<ProductResponse> search(@RequestParam("name") String name){return service.searchByName(name);} }
